  --brand-purple-400: #a25bff;
  --text-chat: 14px;
  --text-chat-line: 21px;
  --text-assistant: 16px;
  --text-assistant-line: 24px;
  --text-meta: 13px;
  --text-meta-line: 18px;
  --text-small: 12px;
  --text-small-line: 16px;
  --font-weight-body: 430;
  --font-weight-strong: 510;
  --thread-content-max-width: 736px;
  --sidebar-width: 340px;
  --topbar-height: 36px;
  --row-height: 30px;
  --transition-duration-basic: .15s;
