/* FORGE semantic extensions: statuses and surfaces outside the captured subset.
   Static system fonts approximate captured 430 / 510 weights with 400 / 500. */
:root {
  --color-text-secondary: rgba(13, 13, 13, .72);
  --color-background-nav-active: rgba(13, 13, 13, .055);
  --color-background-control-subtle: rgba(13, 13, 13, .03);
  --color-border-strong: rgba(13, 13, 13, .118);
  --color-background-command: rgba(13, 13, 13, .055);
  --color-status-error: #a24740;
  --color-status-warning: #966a36;
  --color-background-warning: #fcf8f1;
  --color-border-warning: #e3d5bf;
  --color-scrollbar: rgba(13, 13, 13, .18);
  --color-empty-symbol: rgba(13, 13, 13, .3);
  --color-shadow-soft: rgba(0, 0, 0, .04);
  --color-mask-solid: #000000;
  --muted: var(--app-color-text-foreground-tertiary);
  --line: var(--color-border);
  --accent: var(--color-accent);
}
[data-theme="dark"] {
  --color-text-secondary: rgba(252, 252, 252, .72);
  --color-background-nav-active: rgba(252, 252, 252, .078);
  --color-background-control-subtle: rgba(252, 252, 252, .04);
  --color-border-strong: rgba(252, 252, 252, .14);
  --color-background-command: rgba(252, 252, 252, .055);
  --color-status-error: #ff9c94;
  --color-status-warning: #e0b471;
  --color-background-warning: #2a241b;
  --color-border-warning: #66523c;
  --color-scrollbar: rgba(252, 252, 252, .22);
  --color-empty-symbol: rgba(252, 252, 252, .3);
}

/* The reference uses a 52px icon rail and a 288px conversation panel.
   Static system fonts approximate the captured 430 / 510 axes with 400 / 500. */
:root {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", var(--font-sans), Inter, sans-serif;
  font-size: 14px; font-weight: 400; color: var(--color-text);
  background: var(--app-color-background-surface); font-synthesis: none; text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; scrollbar-width: thin; scrollbar-color: var(--color-scrollbar) transparent; }
html, body, #root { height: 100%; margin: 0; overflow: hidden; }
button, input, textarea, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .4; }
button, a, summary, input, textarea, select {
  transition: color var(--transition-duration-basic) var(--ease-out), background-color var(--transition-duration-basic) var(--ease-out), border-color var(--transition-duration-basic) var(--ease-out);
}
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
[hidden] { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.app-shell { display: grid; grid-template-columns: var(--sidebar-width) minmax(0,1fr); grid-template-rows: 36px minmax(0,1fr); height: 100dvh; overflow: hidden; background: var(--app-color-background-surface); }

/* Full window application chrome, matching the supplied desktop reference. */
.desktop-chrome { grid-column: 1 / -1; height: 36px; display: flex; align-items: center; justify-content: space-between; padding: 0 12px 0 0; }
.desktop-chrome-leading { display: flex; align-items: center; gap: 6px; color: var(--muted); }
.desktop-chrome-leading > span { display: grid; place-items: center; width: 28px; height: 28px; }
.desktop-chrome-leading > span:first-child, .desktop-chrome-leading > span:nth-child(2) { opacity: .45; }
.desktop-menu { display: flex; align-items: center; gap: 2px; margin-left: 4px; }
.desktop-menu > span { padding: 3px 10px; font-size: 13px; line-height: 22px; }
.connection-indicator { font-size: 11px; line-height: 16px; color: var(--muted); white-space: nowrap; }
.status-dot { display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--muted); }
.status-dot.on { background: var(--color-accent); }

/* White, two-part sidebar. Navigation and the conversation list are distinct. */
.rail { display: grid; grid-template-columns: 52px 288px; min-width: 0; min-height: 0; background: var(--app-color-background-surface); }
.primary-rail { display: flex; flex-direction: column; align-items: center; padding: 16px 8px 12px; min-height: 0; }
.primary-nav { display: flex; flex-direction: column; gap: 8px; }
.nav-item, .profile-button { width: 36px; height: 36px; padding: 8px; border: 0; border-radius: 10px; background: transparent; color: var(--muted); display: grid; place-items: center; }
.nav-item.active { color: var(--color-text); background: var(--color-background-nav-active); }
.nav-item:hover, .profile-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.nav-icon { width: 20px; height: 20px; flex: none; }
.profile-button { margin-top: auto; }
.sidebar-panel { min-width: 0; min-height: 0; display: flex; flex-direction: column; }
/* Settings replaces the conversation list, while the primary icon rail stays available. */
.app-shell.settings-open { grid-template-columns: 52px minmax(0,1fr); }
.settings-open .rail { grid-template-columns: 52px; }
.settings-open .sidebar-panel { display: none; }
.sidebar-heading { height: 60px; display: flex; align-items: center; gap: 4px; padding: 0 16px; }
.sidebar-heading > strong { font-size: 18px; font-weight: 500; line-height: 24px; }
.sidebar-heading > svg { width: 12px; height: 12px; color: var(--muted); }
.sidebar-heading-tools { display: flex; align-items: center; gap: 20px; margin-left: auto; color: var(--muted); }
.sidebar-heading-tools svg { width: 16px; height: 16px; }
.sidebar-new-chat { display: flex; align-items: center; gap: 8px; flex: none; height: 30px; margin: 0 8px 16px; padding: 0 8px; border: 0; border-radius: 12.5px; background: transparent; text-align: left; font-size: 13px; }
.sidebar-new-chat:hover, .thread-row:hover { background: var(--color-background-secondary-ghost-hover); }
.sidebar-scroll { min-height: 0; flex: 1; overflow: auto; padding: 0 0 16px; }
.sidebar-section-title { display: flex; align-items: center; justify-content: space-between; min-height: 25px; padding: 4px 16px; color: var(--muted); font-size: 13px; line-height: 21px; }
.sidebar-section-title svg { width: 14px; height: 14px; }
.thread-row { display: block; width: 100%; min-height: 30px; border: 0; border-radius: 12.5px; background: transparent; padding: 5px 16px 5px 32px; text-align: left; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; line-height: 20px; }
.thread-row.active { background: var(--color-background-nav-active); }
.workspace-section { margin-top: 24px; }
.sidebar-workspace { display: flex; align-items: center; gap: 8px; padding: 5px 16px; font-size: 13px; line-height: 20px; }
.sidebar-workspace svg { flex: none; color: var(--muted); }
.sidebar-workspace span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sidebar-connection:empty { display: none; }
.connect-banner { padding: 12px 16px 20px; font-size: 12px; line-height: 18px; color: var(--muted); }
.connect-banner strong { color: var(--color-text); font-size: 12px; font-weight: 500; }
.connect-banner p { margin: 4px 0 8px; }
.connect-controls { display: flex; gap: 6px; }
.connect-controls input { width: 100%; min-width: 0; padding: 6px 8px; border: 1px solid var(--color-border); border-radius: 8px; background: var(--app-color-background-control); font-size: 12px; }

/* Home and an opened conversation have different compositions in the reference. */
.conversation-shell { position: relative; min-width: 0; min-height: 0; margin: 0 4px 4px 0; display: flex; flex-direction: column; background: var(--app-color-background-surface); }
.topbar { height: 56px; flex: none; padding: 10px 24px; border-bottom: 1px solid var(--color-border-subtle); }
.topbar-title h1 { margin: 0; font-size: 13px; line-height: 18px; font-weight: 500; }
.topbar-title small { display: block; margin-top: 2px; font-size: 12px; line-height: 16px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.timeline { flex: 1; min-height: 0; overflow: auto; padding: 24px 24px 120px; }
.timeline > * { width: 100%; min-width: 0; margin-inline: auto; }
.home-state .topbar { display: none; }
.home-state .timeline { display: grid; place-items: center; padding: 0 24px; }
.empty-conversation { display: flex; flex-direction: column; align-items: center; gap: 24px; width: 100%; transform: translateY(-16px); text-align: center; }
.empty-symbol { width: 56px; height: 56px; color: var(--color-empty-symbol); }
.empty-conversation h2 { margin: 0; font-size: 28px; line-height: 33.6px; font-weight: 500; color: var(--color-text); }
.empty-conversation p { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.message { position: relative; display: flex; flex-direction: column; gap: 0; margin: 0 auto 32px; }
.message-body { min-width: 0; overflow-wrap: anywhere; white-space: pre-wrap; font-size: 16px; line-height: 24px; }
.message.from-user { align-items: flex-end; margin-bottom: 24px; }
.message.from-user .message-body { max-width: min(80%,560px); border-radius: 20px; padding: 10px 16px; background: var(--color-background-user-message); color: var(--color-text-user-message); font-size: 14px; line-height: 21px; }
.message.from-agent .message-body { padding: 0; border-radius: 0; background: none; }
.message-meta { position: absolute; bottom: -23px; inset-inline-start: 0; display: flex; align-items: center; gap: 8px; height: 20px; font-size: 12px; line-height: 16px; color: var(--muted); }
.message.from-user .message-meta { inset-inline-start: auto; inset-inline-end: 0; }
.message-meta strong { font-size: 12px; font-weight: 400; }
.message-meta time { font-size: 11px; }
.message-avatar { display: none; }
.history { display: block; margin: 0 auto 24px; }
.text-button { padding: 0; border: 0; background: none; color: var(--color-text-accent); font-size: 12px; line-height: 18px; }
.more { display: block; margin: 16px auto; }
.outgoing-error { margin-top: 8px; color: var(--color-status-error); font-size: 12px; line-height: 18px; overflow-wrap: anywhere; }
.outgoing-error button { margin-left: 8px; }

/* Project backplate, white editor, then the inline controls row. */
.composer-wrap { flex: none; width: 100%; padding: 0 24px 20px; }
.composer-context { position: relative; z-index: 0; display: flex; align-items: center; gap: 24px; height: 40px; width: calc(100% - 28px); margin: 0 auto; padding: 0 16px; border-radius: 20px 20px 0 0; background: var(--app-color-background-surface-under); font-size: 13px; line-height: 18px; }
.composer-context > span { display: inline-flex; align-items: center; gap: 8px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.composer-context > span:first-child { max-width: 45%; }
.composer-context svg { width: 16px; height: 16px; flex: none; }
.composer-context-model { color: var(--color-text-secondary); }
.composer { position: relative; z-index: 1; min-height: 98px; width: 100%; margin: 0 auto; padding: 10px 12px 8px; border: 1px solid var(--color-border); border-radius: 22px; background: var(--app-color-background-surface); box-shadow: 0 2px 12px var(--color-shadow-soft); }
.composer textarea { display: block; width: 100%; height: 40px; min-height: 40px; max-height: 180px; padding: 2px 0; border: 0; outline: none; resize: none; background: transparent; color: var(--color-text); font-size: 14px; line-height: 20px; }
.composer textarea::placeholder { color: var(--muted); }
.composer-bottom { display: flex; align-items: center; gap: 12px; height: 28px; margin-top: 8px; font-size: 13px; line-height: 18px; color: var(--muted); }
.composer-add { display: grid; place-items: center; width: 20px; height: 24px; color: var(--color-text); }
.composer-add svg { width: 20px; height: 20px; }
.composer-model { display: inline-flex; align-items: center; gap: 4px; margin-left: auto; color: var(--color-text); white-space: nowrap; font-size: 13px; }
.composer-model svg { color: var(--muted); width: 12px; height: 12px; }
.send-button { display: grid; place-items: center; flex: none; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 50%; background: var(--color-text); color: var(--app-color-background-surface); font-size: 20px; line-height: 1; }
.send-button:disabled { opacity: 1; background: var(--color-background-secondary-ghost-hover); color: var(--muted); }
.home-state .composer { max-width: 736px; }
.home-state .composer-context { max-width: 708px; }
.home-state .composer-wrap { padding-bottom: 16px; }
.send-error, .action-error { margin: 8px auto 0; color: var(--color-status-error); font-size: 12px; line-height: 18px; overflow-wrap: anywhere; }
.action-error { padding: 0 24px 8px; }
.new-messages { position: absolute; z-index: 3; bottom: 172px; left: 50%; transform: translateX(-50%); padding: 6px 12px; border: 1px solid var(--color-border); border-radius: 999px; background: var(--app-color-background-surface); box-shadow: var(--shadow-lg); font-size: 12px; line-height: 18px; white-space: nowrap; }
.maintenance-banner { padding: 10px 24px; background: var(--app-color-background-surface-under); border-bottom: 1px solid var(--color-border-subtle); color: var(--muted); font-size: 12px; line-height: 18px; }

/* Activity is text; only concrete resources and terminal output use cards. */
.event-group { margin: 0 auto 24px; color: var(--muted); }
.event-line { margin: 0; }
.event-group > summary, .event-line > summary { display: inline-flex; align-items: center; gap: 4px; max-width: 100%; height: 21px; padding: 0; border: 0; border-radius: 0; background: none; color: var(--muted); font-size: 14px; line-height: 21px; font-weight: 400; cursor: pointer; list-style: none; }
.event-group > summary::-webkit-details-marker, .event-line > summary::-webkit-details-marker { display: none; }
.event-group > summary:hover, .event-line > summary:hover { color: var(--color-text); }
.event-group > summary svg, .event-line > summary svg { width: 16px; height: 16px; flex: none; }
.event-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.event-mode { color: inherit; font-size: 12px; }
.event-failed { color: var(--color-status-error); }
.event-line.unknown .event-failed { color: var(--color-status-warning); }
[data-chevron] { opacity: .7; transition: transform var(--transition-duration-basic) var(--ease-out); }
[aria-expanded="true"] > [data-chevron] { transform: rotate(90deg); }
.detail-collapsible { overflow: hidden; height: 0; opacity: 0; margin-inline-start: -8px; padding-inline-start: 8px; transition: height var(--transition-duration-basic) var(--ease-out), opacity var(--transition-duration-basic) var(--ease-out); }
.event-detail { display: flex; flex-direction: column; gap: 12px; padding: 12px 0 0 24px; border: 0; background: none; color: var(--muted); font-size: 13px; line-height: 20px; }
.event-line .event-detail { gap: 8px; padding: 8px 0 4px 24px; }
.event-detail p { margin: 0; }
.event-detail dl { display: block; margin: 8px 0; }
.event-detail dl > div { display: flex; gap: 8px; }
.event-detail dt { flex: none; min-width: 64px; }
.event-detail dd { min-width: 0; flex: 1; overflow-wrap: anywhere; }
.event-detail small { font-size: 12px; line-height: 16px; }
.command-card { display: flex; flex-direction: column; min-width: 0; overflow: hidden; border: 0.8px solid var(--color-border-strong); border-radius: 12.5px; background: var(--color-background-command); }
.command-card > header { padding: 4px 8px; color: var(--muted); font-size: 13px; line-height: 18px; }
.command-line { position: relative; min-width: 0; }
.command-card .cmd { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; padding: 8px 32px 0 8px; white-space: pre-wrap; word-break: break-word; color: var(--color-text-secondary); font: 400 13px/20px var(--font-mono); }
.command-card .cmd::before { content: "$"; margin-inline-end: 1ch; color: var(--muted); }
.command-card .out { display: flex; flex-direction: column-reverse; max-height: 144px; min-width: 0; overflow: auto; padding: 8px; white-space: pre; color: var(--color-text-secondary); font: 500 13px/20px var(--font-mono); }
.command-card .out code { font: inherit; color: inherit; }
.command-card .copy-btn { position: absolute; top: 4px; right: 4px; display: grid; place-items: center; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 8px; background: none; color: var(--muted); }
.command-card .copy-btn:hover { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
.command-no-output { margin: 0; padding: 8px; color: var(--muted); font-size: 12px; line-height: 16px; }
.vertical-scroll-fade-mask { --edge-fade-distance: 2rem; mask-image: linear-gradient(to bottom, transparent 0, var(--color-mask-solid) var(--edge-fade-distance), var(--color-mask-solid) calc(100% - var(--edge-fade-distance)), transparent 100%); }
.resource-card { display: flex; align-items: center; gap: 12px; padding: 12px; min-width: 0; border: 1px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface-under); }
.resource-icon { display: grid; place-items: center; width: 40px; height: 40px; flex: none; border-radius: 12.5px; background: var(--color-background-secondary-ghost-hover); }
.resource-icon svg { width: 24px; height: 24px; }
.resource-card strong { display: block; font-size: 14px; line-height: 21px; color: var(--color-text); overflow-wrap: anywhere; }
.resource-card small { font-size: 13px; line-height: 18px; }
.timeline-updates { margin: 24px auto; }
.timeline-updates-label { margin-bottom: 8px; color: var(--muted); font-size: 12px; line-height: 16px; }
.timeline-update { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; margin: 8px 0; padding: 12px; text-align: left; border: 1px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface); }
.timeline-update:hover { background: var(--color-background-secondary-ghost-hover); }
.timeline-update strong, .timeline-update small { display: block; overflow-wrap: anywhere; }
.timeline-update strong { font-size: 13px; line-height: 18px; font-weight: 500; }
.timeline-update small { margin-top: 4px; color: var(--muted); font-size: 12px; line-height: 16px; }
.approval-card { flex-direction: column; align-items: stretch; gap: 8px; }
.approval-summary { display: flex; justify-content: space-between; gap: 12px; padding: 0; border: 0; background: none; text-align: left; }
.approval-card dl { margin: 4px 0; }
