import type { ReactNode } from "react";
import { isClosedQuest, needsQuestAttention, statusLabel } from "./presentation";

export interface WorkspaceSidebarProps {
  connected: boolean;
  workspaceId: string;
  workspaceRoot: string;
  quests: Array<{ id: string; title: string; status: string }>;
  selectedId: string;
  chatActive: boolean;
  ready: boolean;
  questError: string;
  approvalError: string;
  pendingApprovals: number;
  onChat: () => void;
  onQuest: (id: string) => void;
  onTasks: () => void;
  onApprovals: () => void;
  children: ReactNode;
}

export default function WorkspaceSidebar({
  connected, workspaceId, workspaceRoot, quests, selectedId, chatActive, ready,
  questError, approvalError, pendingApprovals, onChat, onQuest, onTasks,
  onApprovals, children,
}: WorkspaceSidebarProps) {
  const tasksKnown = connected && ready && !questError;
  const approvalsKnown = connected && ready && !approvalError;
  const activeQuests = quests.filter((quest) => !isClosedQuest(quest.status));
  const attentionCount = activeQuests.filter((quest) => needsQuestAttention(quest.status)).length;
  const pendingLabel = !connected ? "未连接" : !ready ? "同步中" : "暂不可用";
  const workspacePath = connected ? workspaceRoot || workspaceId : "";
  const workspaceName = workspacePath.replace(/[\\/]+$/, "").split(/[\\/]/).pop() || "工作空间";

  return <div className="sidebar-panel">
    <div className="sidebar-heading"><strong>FORGE</strong><small>长期任务工作空间</small></div>
    <div className="sidebar-workspace" title={workspacePath || undefined}>
      <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 7h7l2 2h9v11H3zM3 7V4h7l2 3" /></svg>
      <div><strong>{workspaceName}</strong><small>{workspacePath || "连接后显示工作空间"}</small></div>
    </div>
    <div className="sidebar-scroll">
      <button type="button" className={`thread-row${chatActive ? " active" : ""}`} aria-label="长期对话" aria-current={chatActive ? "page" : undefined} onClick={onChat}>
        <strong>长期对话</strong><small>提出目标、追问进展、继续任务</small>
      </button>

      <section className="sidebar-attention">
        <div className="sidebar-section-title"><span>需要处理</span><small>本次已加载</small></div>
        <div className="sidebar-attention-row"><span>待审批操作</span><strong>{approvalsKnown ? pendingApprovals : pendingLabel}</strong></div>
        <div className="sidebar-attention-row"><span>待处理任务</span><strong>{tasksKnown ? attentionCount : pendingLabel}</strong></div>
        {approvalError && <p className="sidebar-notice">审批状态暂不可用</p>}
        {approvalsKnown && pendingApprovals > 0 && <button type="button" className="text-button sidebar-action" onClick={onApprovals}>查看待审批</button>}
      </section>

      <section className="sidebar-tasks">
        <div className="sidebar-section-title"><span>活跃任务</span>{tasksKnown && <small>{activeQuests.length} 项已加载</small>}</div>
        {!connected ? <p className="sidebar-notice">连接后显示后台任务</p>
          : !ready ? <p className="sidebar-notice">正在同步任务…</p>
          : questError ? <p className="sidebar-notice">任务列表暂不可用</p>
          : activeQuests.length === 0 ? <p className="sidebar-notice">暂无活跃任务。在对话中描述你的目标。</p>
          : activeQuests.slice(0, 4).map((quest) => <button
            type="button" key={quest.id}
            className={`sidebar-quest${!chatActive && selectedId === quest.id ? " selected" : ""}${needsQuestAttention(quest.status) ? " is-attention" : ""}`}
            aria-current={!chatActive && selectedId === quest.id ? "page" : undefined}
            onClick={() => onQuest(quest.id)}
          ><span>{quest.title}</span><small className="state-label">{statusLabel(quest.status)}</small></button>)}
        <button type="button" className="text-button sidebar-action" disabled={!connected} onClick={onTasks}>查看全部任务</button>
      </section>
    </div>
    <div className="sidebar-connection">{children}</div>
  </div>;
}

import type { ReactNode } from "react";
import { namesLabel, statusLabel } from "./presentation";

type Row = Record<string, unknown>;

export interface WorkspaceQuest {
  id: string;
  title: string;
  status: string;
  version: number;
  goal: string;
}

export interface QuestWorkspaceProps {
  quests: WorkspaceQuest[];
  selected: WorkspaceQuest | null;
  selectedId: string;
  connected: boolean;
  error: string;
  hasMore: boolean;
  onSelect: (id: string) => void;
  onLoadMore: () => void;
  plan: Row | null;
  planNotice: ReactNode;
  blocked: boolean;
  onApprove: () => void;
  grants: ReactNode;
}

const text = (value: unknown, fallback = "未知"): string => value == null || value === "" ? fallback : String(value);
const records = (value: unknown): Row[] => Array.isArray(value)
  ? value.filter((item): item is Row => !!item && typeof item === "object" && !Array.isArray(item)) : [];

const QUEST_PHASES: Record<string, string> = {
  proposed: "目标已提出，后续计划与团队仍以实际提案为准。",
  awaiting_approval: "任务正在等待批准。请核对计划、任务团队及审批中心中需要确认的内容。",
  approved: "任务已批准；执行仍需满足当前计划、团队、工具权限与预算约束。",
  queued: "任务已进入队列，等待满足资源与执行条件。",
  running: "任务处于运行阶段。运行活动中可查看已记录的成员执行情况。",
  blocked: "任务已阻塞。请结合运行活动、审批与权限记录核对原因。",
  paused: "任务已暂停，当前记录保留在此工作空间。",
  needs_input: "任务需要补充信息，请回到长期对话继续说明。",
  reviewing: "任务正在复核。请以验证与最终任务状态判断结果。",
  completed: "任务状态为已完成，可通过计划与运行活动回查执行和验证记录。",
  failed: "任务已失败。请查看运行活动，并在长期对话中讨论后续处理。",
  cancelled: "任务已取消，历史计划与执行记录仍可回查。",
  rejected: "任务已拒绝，可查看历史计划与审批记录了解处理经过。",
};

function costLimit(plan: Row): string {
  if (plan.max_cost_microunits === null) return "未设置";
  if (plan.max_cost_microunits === undefined) return "未知";
  return `${text(plan.max_cost_microunits)} 微单位 · ${text(plan.cost_currency, "币种未知")}`;
}

function criteria(value: unknown): string {
  return Array.isArray(value) ? value.map((item) => text(item)).join("；") || "未提供" : text(value, "未提供");
}

export default function QuestWorkspace({
  quests, selected, selectedId, connected, error, hasMore, onSelect, onLoadMore,
  plan, planNotice, blocked, onApprove, grants,
}: QuestWorkspaceProps) {
  const nodes = records(plan?.nodes);
  return <div className="quest-workspace">
    <div className="quest-list">
      <div className="section-heading"><span>后台任务</span><span>{quests.length}{hasMore ? "+" : ""} 项已加载</span></div>
      {error && <p className="notice error" role="alert">任务列表加载失败：{error}</p>}
      {!quests.length ? <div className="quest-empty">
        <p>{connected ? "暂无后台任务" : "连接 Core 后显示任务"}</p>
        <p className="notice">在长期对话中提出目标，计划、团队与执行记录会归到对应任务。</p>
      </div> : <div className="list">{quests.map((quest) => <button
        type="button" key={quest.id}
        className={selectedId === quest.id ? "list-row selected" : "list-row"}
        aria-label={`${quest.title} ${quest.id} ${quest.status}`}
        aria-current={selectedId === quest.id ? "page" : undefined}
        onClick={() => onSelect(quest.id)}
      ><span><strong>{quest.title}</strong><small>{quest.goal}</small></span><span className="state-label">{statusLabel(quest.status)}</span></button>)}</div>}
      {hasMore && <button type="button" className="text-button more" onClick={onLoadMore}>加载更多任务</button>}
    </div>

    <div className="quest-detail">
      {!selected ? <div className="quest-empty quest-empty-selection"><h3>选择任务，查看计划与权限</h3><p className="notice">每个任务的计划、团队、审批与执行记录保持独立，结果回到同一个长期对话。</p></div> : <>
        <div className="detail quest-overview">
          <span className="eyebrow">当前任务</span>
          <h3>{selected.title}</h3>
          <p className="quest-goal">{selected.goal}</p>
          <div className="quest-phase"><strong>{statusLabel(selected.status)}</strong><span>版本 {selected.version}</span></div>
          <p className="notice">{QUEST_PHASES[selected.status] || "当前阶段以服务端原始状态为准。"}</p>
        </div>

        <section className="quest-plan">
          <div className="section-heading spaced"><span>执行计划</span>{plan && <span>{nodes.length} 个节点</span>}</div>
          {planNotice}
          {plan && <>
            <dl className="quest-plan-facts"><dt>计划版本</dt><dd>{text(plan.plan_revision)}</dd><dt>状态</dt><dd>{statusLabel(plan.status)}</dd><dt>总 Token 预算</dt><dd>{text(plan.max_total_tokens)}</dd><dt>费用上限</dt><dd>{costLimit(plan)}</dd></dl>
            <div className="quest-plan-nodes">{nodes.map((node, index) => <div className="plan-node" key={text(node.key, String(index))}>
              <div className="plan-node-heading"><strong>{index + 1}. {text(node.objective)}</strong><span className="state-label">{statusLabel(node.status)}</span></div>
              <small>Token 预算：{text(node.budget_tokens)}</small>
              <small>允许工具：{namesLabel(node.allowed_tools)}</small>
              <small>验收条件：{criteria(node.success_criteria)}</small>
            </div>)}</div>
            <details className="quest-technical"><summary>技术详情</summary><dl><dt>任务 ID</dt><dd className="mono break">{selected.id}</dd><dt>计划摘要</dt><dd className="mono break">{text(plan.digest)}</dd></dl><pre>{JSON.stringify(plan, null, 2)}</pre></details>
            {plan.status === "proposed" && typeof plan.digest === "string" && <div className="button-row"><button type="button" className="button primary" disabled={blocked} onClick={onApprove}>批准此计划</button></div>}
          </>}
          {!plan && <details className="quest-technical"><summary>技术详情</summary><dl><dt>任务 ID</dt><dd className="mono break">{selected.id}</dd><dt>原始状态</dt><dd>{selected.status}</dd></dl></details>}
        </section>
      </>}
      {grants}
    </div>
  </div>;
}

import { SettingsRow } from "./SettingsView";

type BudgetRecord = Record<string, unknown>;

const finiteNonnegative = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value) && value >= 0;
const budgetText = (value: unknown) => typeof value === "string" && value.trim() ? value : "未知";

export function formatBudgetNumber(value: unknown): string {
  return finiteNonnegative(value) ? value.toLocaleString("zh-CN", { maximumFractionDigits: 6 }) : "未知";
}

export function formatBudgetCost(microunits: unknown, currency: unknown): string {
  const denomination = budgetText(currency);
  if (!finiteNonnegative(microunits)) return denomination === "未知" ? "未知" : `未知（${denomination}）`;
  const amount = (microunits / 1_000_000).toLocaleString("zh-CN", { maximumFractionDigits: 6 });
  return denomination === "未知" ? `${amount}（币种未知）` : `${amount} ${denomination}`;
}

export function formatBudgetRecoveryTime(value: unknown): string {
  if (typeof value !== "number" || !Number.isFinite(value)) return "未知";
  const date = new Date(value * 1000);
  return Number.isFinite(date.getTime()) ? date.toLocaleString() : "未知";
}

export default function BudgetOverview({ budget }: { budget: BudgetRecord }) {
  const unsettled = Array.isArray(budget.recent_unsettled) ? budget.recent_unsettled : null;

  return <>
    <section className="settings-section">
      <h2 className="settings-section-title">Token 账本</h2>
      <SettingsRow label="已确认用量" description="已经记录的确认 Token 用量。">{formatBudgetNumber(budget.known_tokens)}</SettingsRow>
      <SettingsRow label="未结算预留" description="尚未确认的输入和输出 Token 预留。">{formatBudgetNumber(budget.reserved_tokens)}</SettingsRow>
      <SettingsRow label="迁移期上界" description="历史预算迁移时计入的 Token 上界。">{formatBudgetNumber(budget.opening_tokens)}</SettingsRow>
      <SettingsRow label="保守计入 Token" description="已确认用量 + 未结算预留 + 迁移期上界；用于预算准入，不是实际消耗。">{formatBudgetNumber(budget.charged_tokens)}</SettingsRow>
      <SettingsRow label="Token 上限" description="当前工作空间模型调用的累计预算上限。">{formatBudgetNumber(budget.token_limit)}</SettingsRow>
      {budget.token_limit === 0 && <p className="notice">Token 上限为 0，当前预算未开放，模型调用受限。</p>}
    </section>

    <section className="settings-section">
      <h2 className="settings-section-title">并发与费用</h2>
      <SettingsRow label="并发占用" description="当前占用的模型调用并发槽 / 并发上限。">{formatBudgetNumber(budget.active_reservations)} / {formatBudgetNumber(budget.concurrency_limit)}</SettingsRow>
      <SettingsRow label="费用上限" description="按配置币种显示费用上限；未提供的金额或币种保持未知。">{formatBudgetCost(budget.cost_limit_microunits, budget.currency)}</SettingsRow>
      <p className="notice">费用信息缺失不表示免费；费用上限也不代表已经发生的费用。</p>
    </section>

    <section className="settings-section">
      <h2 className="settings-section-title">最近未结算请求</h2>
      <p className="notice">显示当前返回的最近记录。请求超时不表示远端已取消，也不表示预留已经释放。</p>
      {unsettled === null ? <p className="notice">未结算请求信息未知。</p> : unsettled.length === 0 ? <p className="notice">当前列表没有未结算请求。</p> : unsettled.map((value, index) => {
        const item: BudgetRecord = value && typeof value === "object" && !Array.isArray(value) ? value as BudgetRecord : {};
        return <div className="data-row budget-unsettled-record" key={index}>
          <strong>{budgetText(item.purpose)}</strong>
          <dl>
            <dt>状态</dt><dd>{budgetText(item.code)}</dd>
            <dt>输入预留</dt><dd>{formatBudgetNumber(item.input_reserved)}</dd>
            <dt>输出预留</dt><dd>{formatBudgetNumber(item.output_reserved)}</dd>
            <dt>隔离至</dt><dd>{formatBudgetRecoveryTime(item.recover_after)}</dd>
          </dl>
        </div>;
      })}
    </section>
  </>;
}

