        {view === "teams" && panelItems.length > 0 && <div className="list">{panelItems.map((item, index) => <div className="data-row" key={text(item.id, String(index))}><strong>团队提案 · {text(item.status)}</strong><small>计划版本 {text(item.plan_revision)}</small><p className="mono break">{text(item.proposal_digest)}</p>{typeof item.body === "object" && item.body !== null && <><dl><dt>总 token 预算</dt><dd>{text(((item.body as Row).limits as Row | undefined)?.max_total_tokens)}</dd><dt>费用上限</dt><dd>{text(((item.body as Row).limits as Row | undefined)?.max_cost_microunits)}</dd></dl>{rows((item.body as Row).members).map((member, memberIndex) => <div className="plan-node" key={text(member.role_id, String(memberIndex))}><strong>{text(member.role_id)}</strong><small>模型：{text(member.provider_id)} / {text(member.model_id)}</small><small>工具权限：{names(member.tool_scope)}</small><small>Token 预算：{text(member.estimated_tokens)}</small></div>)}</>}<TechnicalDetails value={item} />{item.status === "proposed" && selected && typeof item.proposal_digest === "string" && <button className="button primary" disabled={actionBusy || writesBlocked} onClick={() => { if (window.confirm(`批准团队？\n任务版本：${selected.version}\n计划版本：${text(item.plan_revision)}\n摘要：${text(item.proposal_digest)}\n请先检查成员、权限和预算。`)) void perform(`/api/quests/${encodeURIComponent(selected.id)}/teams/approve`, { expected_version: selected.version, plan_revision: item.plan_revision, proposal_digest: item.proposal_digest }); }}>批准此团队</button>}</div>)}</div>}
        {view === "approvals" && panelItems.length > 0 && <><div className="list">{panelItems.map((item, index) => <div className="data-row" key={text(item.id, String(index))}><strong>{text(item.action_type)} · {text(item.status)}</strong><dl><dt>风险</dt><dd>{text(item.risk)}</dd><dt>范围</dt><dd className="break">{text(item.resource_scope)}</dd><dt>计划版本</dt><dd>{text(item.plan_revision)}</dd><dt>参数摘要</dt><dd className="mono break">{text(item.parameter_digest)}</dd><dt>原因</dt><dd>{text(item.reason)}</dd><dt>过期时间</dt><dd>{text(item.expires_at)}</dd></dl>{item.status === "PENDING" && <div className="button-row">{(["APPROVED", "REJECTED"] as const).map((decision) => <button key={decision} className={decision === "APPROVED" ? "button primary" : "button"} disabled={actionBusy || writesBlocked || typeof item.parameter_digest !== "string" || typeof item.plan_revision !== "number"} onClick={() => { if (window.confirm(`${decision === "APPROVED" ? "批准" : "拒绝"}此操作？\n风险：${text(item.risk)}\n范围：${text(item.resource_scope)}\n计划版本：${text(item.plan_revision)}\n参数摘要：${text(item.parameter_digest)}`)) void perform(`/api/approvals/${encodeURIComponent(text(item.id))}/decision`, { decision, expected_digest: item.parameter_digest, expected_plan_revision: item.plan_revision }); }}>{decision === "APPROVED" ? "批准" : "拒绝"}</button>)}</div>}</div>)}</div>{approvalCursor && <button className="text-button more" disabled={visiblePanel.loading} onClick={() => void loadPanelPage()}>加载更早的审批</button>}</>}
        {view === "memory" && panelItems.length > 0 && <><div className="list">{(panelItems as MemoryItem[]).map((item) => <div className="data-row" key={item.id}><strong>{item.statement}</strong><small>{text(item.layer)} · {text(item.kind)} · {text(item.status)} · {text(item.freshness, "新鲜度未知")}</small><dl><dt>来源</dt><dd className="break">{item.source_refs?.join(", ") || "未知"}</dd><dt>记录时间</dt><dd>{text(item.created_at)}</dd><dt>有效至</dt><dd>{text(item.valid_until, "未指定")}</dd><dt>可信度</dt><dd>{text(item.confidence, "未知")}</dd><dt>关联任务</dt><dd className="break">{Array.isArray(item.related_quest_ids) ? item.related_quest_ids.join(", ") || "无" : "未知"}</dd></dl>{item.conflicted === true && <p className="warning">存在冲突，请核对来源。</p>}{/^[a-f0-9]{32}$/i.test(item.id) && <button className="button" disabled={actionBusy || writesBlocked} onClick={() => { if (window.confirm(`撤销这条记忆？\n${item.statement}`)) void perform(`/api/memory/${encodeURIComponent(item.id)}/revoke`); }}>撤销记忆</button>}</div>)}</div>{memoryCursor && <button className="text-button more" disabled={visiblePanel.loading} onClick={() => void loadPanelPage()}>加载更多记忆</button>}</>}

import type { ReactNode } from "react";
import { namesLabel, statusLabel } from "./presentation";

type Row = Record<string, unknown>;

export interface WorkspaceQuest {
  id: string;
  title: string;
  status: string;
  version: number;
  goal: string;
}

export interface QuestWorkspaceProps {
  quests: WorkspaceQuest[];
  selected: WorkspaceQuest | null;
  selectedId: string;
  connected: boolean;
  error: string;
  hasMore: boolean;
  onSelect: (id: string) => void;
  onLoadMore: () => void;
  plan: Row | null;
  planNotice: ReactNode;
  blocked: boolean;
  onApprove: () => void;
  grants: ReactNode;
}

const text = (value: unknown, fallback = "未知"): string => value == null || value === "" ? fallback : String(value);
const records = (value: unknown): Row[] => Array.isArray(value)
  ? value.filter((item): item is Row => !!item && typeof item === "object" && !Array.isArray(item)) : [];

const QUEST_PHASES: Record<string, string> = {
  proposed: "目标已提出，后续计划与团队仍以实际提案为准。",
  awaiting_approval: "任务正在等待批准。请核对计划、任务团队及审批中心中需要确认的内容。",
  approved: "任务已批准；执行仍需满足当前计划、团队、工具权限与预算约束。",
  queued: "任务已进入队列，等待满足资源与执行条件。",
  running: "任务处于运行阶段。运行活动中可查看已记录的成员执行情况。",
  blocked: "任务已阻塞。请结合运行活动、审批与权限记录核对原因。",
  paused: "任务已暂停，当前记录保留在此工作空间。",
  needs_input: "任务需要补充信息，请回到长期对话继续说明。",
  reviewing: "任务正在复核。请以验证与最终任务状态判断结果。",
  completed: "任务状态为已完成，可通过计划与运行活动回查执行和验证记录。",
  failed: "任务已失败。请查看运行活动，并在长期对话中讨论后续处理。",
  cancelled: "任务已取消，历史计划与执行记录仍可回查。",
  rejected: "任务已拒绝，可查看历史计划与审批记录了解处理经过。",
};

function costLimit(plan: Row): string {
  if (plan.max_cost_microunits === null) return "未设置";
  if (plan.max_cost_microunits === undefined) return "未知";
  return `${text(plan.max_cost_microunits)} 微单位 · ${text(plan.cost_currency, "币种未知")}`;
}

function criteria(value: unknown): string {
  return Array.isArray(value) ? value.map((item) => text(item)).join("；") || "未提供" : text(value, "未提供");
}

export default function QuestWorkspace({
  quests, selected, selectedId, connected, error, hasMore, onSelect, onLoadMore,
  plan, planNotice, blocked, onApprove, grants,
}: QuestWorkspaceProps) {
  const nodes = records(plan?.nodes);
  return <div className="quest-workspace">
    <div className="quest-list">
      <div className="section-heading"><span>后台任务</span><span>{quests.length}{hasMore ? "+" : ""} 项已加载</span></div>
      {error && <p className="notice error" role="alert">任务列表加载失败：{error}</p>}
      {!quests.length ? <div className="quest-empty">
        <p>{connected ? "暂无后台任务" : "连接 Core 后显示任务"}</p>
        <p className="notice">在长期对话中提出目标，计划、团队与执行记录会归到对应任务。</p>
      </div> : <div className="list">{quests.map((quest) => <button
        type="button" key={quest.id}
        className={selectedId === quest.id ? "list-row selected" : "list-row"}
        aria-label={`${quest.title} ${quest.id} ${quest.status}`}
        aria-current={selectedId === quest.id ? "page" : undefined}
        onClick={() => onSelect(quest.id)}
      ><span><strong>{quest.title}</strong><small>{quest.goal}</small></span><span className="state-label">{statusLabel(quest.status)}</span></button>)}</div>}
      {hasMore && <button type="button" className="text-button more" onClick={onLoadMore}>加载更多任务</button>}
    </div>

    <div className="quest-detail">
      {!selected ? <div className="quest-empty quest-empty-selection"><h3>选择任务，查看计划与权限</h3><p className="notice">每个任务的计划、团队、审批与执行记录保持独立，结果回到同一个长期对话。</p></div> : <>
        <div className="detail quest-overview">
          <span className="eyebrow">当前任务</span>
          <h3>{selected.title}</h3>
          <p className="quest-goal">{selected.goal}</p>
          <div className="quest-phase"><strong>{statusLabel(selected.status)}</strong><span>版本 {selected.version}</span></div>
          <p className="notice">{QUEST_PHASES[selected.status] || "当前阶段以服务端原始状态为准。"}</p>
        </div>

        <section className="quest-plan">
          <div className="section-heading spaced"><span>执行计划</span>{plan && <span>{nodes.length} 个节点</span>}</div>
          {planNotice}
          {plan && <>
            <dl className="quest-plan-facts"><dt>计划版本</dt><dd>{text(plan.plan_revision)}</dd><dt>状态</dt><dd>{statusLabel(plan.status)}</dd><dt>总 Token 预算</dt><dd>{text(plan.max_total_tokens)}</dd><dt>费用上限</dt><dd>{costLimit(plan)}</dd></dl>
            <div className="quest-plan-nodes">{nodes.map((node, index) => <div className="plan-node" key={text(node.key, String(index))}>
              <div className="plan-node-heading"><strong>{index + 1}. {text(node.objective)}</strong><span className="state-label">{statusLabel(node.status)}</span></div>
              <small>Token 预算：{text(node.budget_tokens)}</small>
              <small>允许工具：{namesLabel(node.allowed_tools)}</small>
              <small>验收条件：{criteria(node.success_criteria)}</small>
            </div>)}</div>
            <details className="quest-technical"><summary>技术详情</summary><dl><dt>任务 ID</dt><dd className="mono break">{selected.id}</dd><dt>计划摘要</dt><dd className="mono break">{text(plan.digest)}</dd></dl><pre>{JSON.stringify(plan, null, 2)}</pre></details>
            {plan.status === "proposed" && typeof plan.digest === "string" && <div className="button-row"><button type="button" className="button primary" disabled={blocked} onClick={onApprove}>批准此计划</button></div>}
          </>}
          {!plan && <details className="quest-technical"><summary>技术详情</summary><dl><dt>任务 ID</dt><dd className="mono break">{selected.id}</dd><dt>原始状态</dt><dd>{selected.status}</dd></dl></details>}
        </section>
      </>}
      {grants}
    </div>
  </div>;
}

.settings-content .inspector-header { position: absolute; top: 0; right: 0; min-height: 0; height: 30px; padding: 0; border: 0; }
