.list-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; width: 100%; padding: 8px 10px; border: 0; border-radius: 12.5px; background: none; text-align: left; }
.list-row:hover, .list-row.selected { background: var(--color-background-secondary-ghost-hover); }
