/* ===== runtime style #0 ===== */

      /* Dependency CSS can load before app.css, so establish Tailwind's layer order here. */
      @layer properties, theme, base, components, utilities;

      :root {
        --startup-background: transparent;
        --startup-logo-shimmer-base: rgb(0 0 0 / 0.24);
        --startup-logo-shimmer-peak: rgb(255 255 255 / 0.48);
        --startup-logo-shimmer-soft: rgb(255 255 255 / 0.04);
        --startup-logo-shimmer-tail: rgb(255 255 255 / 0.08);

      }

      :root[data-theme="dark"] {
        --startup-logo-shimmer-base: rgb(255 255 255 / 0.68);
      }

      @media (prefers-color-scheme: dark) {
        :root:not([data-theme]) {
          --startup-logo-shimmer-base: rgb(255 255 255 / 0.68);
        }
      }

      html,
      body {
        margin: 0;
        width: 100%;
        height: 100%;
        background: var(--startup-background);
      }

      body {
        outline: none;
      }

      #root {
        width: 100%;
        height: 100%;
      }

      .startup-loader {
        display: flex;
        width: 100%;
        height: 100%;
        align-items: center;
        justify-content: center;
        background: var(--startup-background);
        -webkit-app-region: drag;
      }

      .startup-loader__logo {
        position: relative;
        width: 56px;
        height: 56px;
        background: var(--startup-logo-shimmer-base);
        clip-path: url("#startup-logo-shape");
      }

      .startup-loader__logo::after {
        content: "";
        position: absolute;
        inset-block: 0;
        left: 0;
        width: 220%;
        background-image: linear-gradient(
          112deg,
          transparent 22%,
          var(--startup-logo-shimmer-soft) 38%,
          var(--startup-logo-shimmer-peak) 49%,
          var(--startup-logo-shimmer-tail) 56%,
          transparent 74%
        );
        animation: startup-openai-blossom-shimmer 2200ms
          cubic-bezier(0.4, 0, 0.2, 1) infinite;
      }

      @media (prefers-reduced-motion: reduce) {
        .startup-loader__logo::after {
          animation: none;
          transform: translateX(calc(-168% / 2.2));
        }
      }

      /* Move the 220%-wide gradient between its original background positions. */
      @keyframes startup-openai-blossom-shimmer {
        0% {
          transform: translateX(calc(-168% / 2.2));
        }

        100% {
          transform: translateX(calc(126% / 2.2));
        }
      }
    
