/* ===== runtime style #2 ===== */
@layer theme {:root:not([data-theme]), [data-theme=""], [data-theme="light"] {--color-background-composer-primary:var(--color-background-primary-solid);
--color-text-composer-primary:var(--color-text-primary-solid);
--color-background-user-message:color-mix(in oklab, var(--color-text) 5%, transparent);
--color-text-user-message:var(--color-text);
--color-background-text-selection:var(--app-color-background-accent-active);
--color-background-attribution-highlight:var(--app-color-background-accent-active);
/* Minimal glue so the real stylesheet drives a static, data-bound app. */

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--color-background-primary, #fff);
  color: var(--color-text, #0d0d0d);
  font-family: var(--font-sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
}

#root { height: 100%; }
#shell { height: 100%; }

/* the app's PageSurface normally comes from its own layout component */
#page-surface {
  min-width: 0;
  position: relative;
}

/* home view: the extracted home layout is height-driven; give it room */
#home-view { min-height: 0; }
#home-view > .contents > .contents { height: 100%; }

/* thread view */
#thread-view { min-height: 0; }
#transcript { min-height: 0; }

/* sidebar keeps its own width; avoid the app's responsive collapse fighting us */
aside.app-shell-left-panel { flex: 0 0 auto; order: -1; }

/* contenteditable placeholder support (the app's ProseMirror normally does this) */
[contenteditable="true"]:empty::before,
[contenteditable="true"] p[data-placeholder]::before {
  content: attr(data-placeholder);
  color: var(--color-text-tertiary, #8f8f8f);
  pointer-events: none;
}

[contenteditable="true"] { outline: none; }

/* markdown spacing inside messages */
.MarkdownRoot-rZKhxa > * + * { margin-top: 0.75em; }
.MarkdownRoot-rZKhxa pre { max-width: 100%; }
.MarkdownRoot-rZKhxa table { border-collapse: collapse; }
.MarkdownRoot-rZKhxa th,
.MarkdownRoot-rZKhxa td { border: 1px solid var(--color-border-subtle, #0002); padding: 4px 8px; }

/* thin scrollbars to match the desktop app */
* { scrollbar-width: thin; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, currentColor 18%, transparent);
  border-radius: 6px;
  border: 3px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-track { background: transparent; }

/* hover-reveal action bars need a real hover target */
.group\/user-message:hover .group-hover\/user-message\:opacity-100,
.group\/agent-message:hover .group-hover\/agent-message\:opacity-100,
.group\/turn-diff:hover .group-hover\/turn-diff\:opacity-100 { opacity: 1; }

/* selected thread row */
[data-app-action-sidebar-thread-selected="true"] {
  background: var(--color-background-secondary-ghost-hover, rgb(0 0 0 / 0.06));
}

/* keep the sidebar scroll area usable */
aside .vertical-scroll-fade-mask { overflow-y: auto; }

.command-card .out code { font: inherit; color: inherit; }
.command-card .copy-btn { position: absolute; top: 4px; right: 4px; display: grid; place-items: center; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 8px; background: none; color: var(--muted); }
.command-card .copy-btn:hover { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
.command-no-output { margin: 0; padding: 8px; color: var(--muted); font-size: 12px; line-height: 16px; }
.vertical-scroll-fade-mask { --edge-fade-distance: 2rem; mask-image: linear-gradient(to bottom, transparent 0, var(--color-mask-solid) var(--edge-fade-distance), var(--color-mask-solid) calc(100% - var(--edge-fade-distance)), transparent 100%); }
.resource-card { display: flex; align-items: center; gap: 12px; padding: 12px; min-width: 0; border: 1px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface-under); }
.resource-icon { display: grid; place-items: center; width: 40px; height: 40px; flex: none; border-radius: 12.5px; background: var(--color-background-secondary-ghost-hover); }
.resource-icon svg { width: 24px; height: 24px; }
.resource-card strong { display: block; font-size: 14px; line-height: 21px; color: var(--color-text); overflow-wrap: anywhere; }
.resource-card small { font-size: 13px; line-height: 18px; }
.timeline-updates { margin: 24px auto; }
.timeline-updates-label { margin-bottom: 8px; color: var(--muted); font-size: 12px; line-height: 16px; }
.timeline-update { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; margin: 8px 0; padding: 12px; text-align: left; border: 1px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface); }
.timeline-update:hover { background: var(--color-background-secondary-ghost-hover); }
.timeline-update strong, .timeline-update small { display: block; overflow-wrap: anywhere; }
.timeline-update strong { font-size: 13px; line-height: 18px; font-weight: 500; }
.timeline-update small { margin-top: 4px; color: var(--muted); font-size: 12px; line-height: 16px; }
.approval-card { flex-direction: column; align-items: stretch; gap: 8px; }
.approval-summary { display: flex; justify-content: space-between; gap: 12px; padding: 0; border: 0; background: none; text-align: left; }
.approval-card dl { margin: 4px 0; }
.approval-card .button-row { margin-top: 0; }

/* Settings groups reflect the workspace, its model runtime, and its data. */
.settings-view { display: grid; grid-template-columns: 288px minmax(0,1fr); min-height: 0; min-width: 0; margin: 0 4px 4px 0; background: var(--app-color-background-surface); }
.settings-nav { display: flex; flex-direction: column; gap: 16px; min-height: 0; width: 288px; padding: 12px 8px 8px; overflow: auto; }
.settings-page-title { flex: none; margin: 0; font-size: 20px; line-height: 26px; font-weight: 500; }
.settings-search { display: flex; align-items: center; gap: 8px; height: 34px; flex: none; margin-top: -8px; padding: 6px 10px; border: 1px solid var(--color-border); border-radius: 10px; color: var(--muted); }
.settings-search svg { flex: none; width: 16px; height: 16px; }
.settings-search input { width: 100%; min-width: 0; padding: 0; border: 0; outline: none; background: none; font-size: 13px; line-height: 20px; }
.settings-nav-section { display: flex; flex-direction: column; gap: 1px; }
.settings-search + .settings-nav-section { margin-top: -4px; }
.settings-nav-group { margin: 0; padding: 8px 8px 4px; font-size: 14px; line-height: 21px; font-weight: 500; color: var(--muted); }
.settings-nav-item { display: flex; align-items: center; width: 100%; height: 30px; padding: 5px 8px; border: 0; border-radius: 12.5px; background: none; text-align: start; font-size: 13px; line-height: 18.5714px; }
.settings-nav-item:hover { background: var(--color-background-secondary-ghost-hover); }
.settings-nav-item.active { background: var(--color-background-nav-active); }
.settings-content { min-width: 0; min-height: 0; padding: 24px 32px; overflow: auto; }
.settings-content-inner { position: relative; width: 100%; max-width: 760px; margin-inline: auto; }
.settings-title { margin: 0 36px 12px 0; font-size: 28px; line-height: 33.6px; font-weight: 500; }
.settings-description { max-width: 620px; margin: 0 0 24px; color: var(--muted); font-size: 13px; line-height: 21px; }
.settings-section + .settings-section { margin-top: 28px; }
.settings-section-title { margin: 0; padding: 0 16px 10px; color: var(--color-text-secondary); font-size: 13px; line-height: 20px; font-weight: 500; }
.settings-section > .notice { margin: 10px 16px 0; }
.budget-unsettled-record { padding-inline: 16px; }
.budget-unsettled-record dl { grid-template-columns: 96px minmax(0,1fr); margin-bottom: 0; }
.settings-row { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); min-height: 53px; }
.settings-row-text { min-width: 0; flex: 1; }
.settings-row-label { font-size: 13px; line-height: 18px; font-weight: 500; }
.settings-row-desc { margin-top: 2px; font-size: 12px; line-height: 16px; color: var(--muted); }
.settings-row-control { display: inline-flex; align-items: center; gap: 6px; flex: none; max-width: 60%; min-width: 0; padding: 4px 12px; border: 1px solid var(--color-border); border-radius: 8px; background: var(--color-background-control-subtle); font-size: 13px; line-height: 18px; overflow-wrap: anywhere; }
.settings-row-value { justify-content: flex-end; max-width: 52%; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--color-text-secondary); text-align: right; }
.settings-content .inspector-header { position: absolute; top: 0; right: 0; min-height: 0; height: 30px; padding: 0; border: 0; }
.settings-content .inspector-header > div { display: none; }
.settings-content .inspector-body { overflow: visible; padding: 0; }
.settings-content .field-label { display: grid; grid-template-columns: minmax(0,1fr) minmax(160px,48%); align-items: center; gap: 24px; margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text); font-size: 13px; line-height: 18px; }
.settings-content .field-label input, .settings-content .field-label textarea, .settings-content .field-label select { padding: 4px 12px; font-size: 13px; line-height: 18px; background: var(--color-background-control-subtle); }
