.settings-row-value { justify-content: flex-end; max-width: 52%; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--color-text-secondary); text-align: right; }
.settings-content .inspector-header { position: absolute; top: 0; right: 0; min-height: 0; height: 30px; padding: 0; border: 0; }
.settings-content .inspector-header > div { display: none; }
.settings-content .inspector-body { overflow: visible; padding: 0; }
.settings-content .field-label { display: grid; grid-template-columns: minmax(0,1fr) minmax(160px,48%); align-items: center; gap: 24px; margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text); font-size: 13px; line-height: 18px; }
.settings-content .field-label input, .settings-content .field-label textarea, .settings-content .field-label select { padding: 4px 12px; font-size: 13px; line-height: 18px; background: var(--color-background-control-subtle); }
.settings-content .check-label { margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); font-size: 13px; }
.settings-content .check-label input { margin-left: auto; order: 1; }

/* Existing management and forms remain available on the main surface. */
.workspace-panel { display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: 0 4px 4px 0; }
.inspector-header { display: flex; align-items: center; justify-content: space-between; flex: none; height: 56px; padding: 10px 24px; border-bottom: 1px solid var(--color-border-subtle); }
.inspector-header h2 { margin: 0; font-size: 14px; line-height: 20px; font-weight: 500; }
.inspector-body { min-height: 0; overflow: auto; padding: 24px; }
.workspace-description { max-width: 760px; margin: 0 0 16px; color: var(--muted); font-size: 12px; line-height: 20px; }
.workspace-intro { max-width: 760px; margin: 0 0 20px; }
.workspace-intro h3 { margin: 0 0 8px; font-size: 20px; line-height: 28px; font-weight: 500; }
.workspace-intro p { max-width: 620px; margin: 0; color: var(--muted); font-size: 13px; line-height: 21px; }
.eyebrow { color: var(--muted); font-size: 10px; line-height: 14px; letter-spacing: .08em; }
.icon-button { display: grid; place-items: center; width: 30px; height: 30px; border: 0; border-radius: 8px; background: none; color: var(--muted); font-size: 18px; }
.icon-button:hover { background: var(--color-background-secondary-ghost-hover); }
.workspace-tabs { display: flex; gap: 20px; margin-bottom: 20px; overflow-x: auto; border-bottom: 1px solid var(--color-border-subtle); }
.workspace-tabs button { flex: none; padding: 8px 0; border-bottom: 2px solid transparent; color: var(--muted); font-size: 13px; white-space: nowrap; }
.workspace-tabs button.active { border-color: var(--color-text); color: var(--color-text); }
.quest-workspace { display: grid; grid-template-columns: 288px minmax(0,1fr); gap: 24px; }
.quest-list { min-width: 0; padding-right: 16px; border-right: 1px solid var(--color-border-subtle); }
.quest-detail { min-width: 0; max-width: 760px; }
.quest-list .list-row > span:first-child { min-width: 0; flex: 1; }
.quest-list .list-row small { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.quest-list .list-row > .state-label { flex: none; padding-top: 2px; font-size: 11px; line-height: 18px; }
.quest-empty { padding: 8px 0 16px; color: var(--color-text-secondary); font-size: 13px; line-height: 20px; }
.quest-empty p { margin: 0 0 8px; }
.quest-empty-selection { padding: 28px 0; }
.quest-empty-selection h3 { margin: 0 0 8px; font-size: 16px; line-height: 24px; font-weight: 500; }
.quest-empty-selection p { max-width: 440px; }
.quest-overview { padding-top: 0; }
.detail.quest-overview h3 { margin: 8px 0; font-size: 22px; line-height: 30px; }
.quest-overview .quest-goal { margin: 0 0 16px; white-space: pre-wrap; overflow-wrap: anywhere; }
.quest-phase { display: flex; align-items: center; gap: 12px; font-size: 12px; line-height: 18px; }
.quest-phase strong { font-weight: 500; }
.quest-phase > span { color: var(--muted); }
.quest-overview .notice { margin: 8px 0 0; font-size: 12px; line-height: 18px; }
.quest-plan-facts { grid-template-columns: 96px minmax(0,1fr); margin: 0 0 20px; }
.plan-node-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.plan-node-heading > strong { min-width: 0; }
.plan-node-heading > .state-label { flex: none; padding-top: 1px; font-size: 11px; line-height: 18px; }
.quest-technical { margin-top: 16px; font-size: 12px; line-height: 18px; }
.quest-technical > summary { width: fit-content; color: var(--muted); }
.quest-technical > summary:hover { color: var(--color-text); }
.quest-technical pre { border-radius: 8px; }
.section-heading { display: flex; justify-content: space-between; margin-bottom: 12px; color: var(--muted); font-size: 12px; line-height: 16px; font-weight: 500; }
.section-heading.spaced { margin-top: 24px; }
.list-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; width: 100%; padding: 8px 10px; border: 0; border-radius: 12.5px; background: none; text-align: left; }
.list-row:hover, .list-row.selected { background: var(--color-background-secondary-ghost-hover); }
.list-row strong, .data-row strong, .plan-node strong { display: block; font-size: 13px; line-height: 20px; font-weight: 500; overflow-wrap: anywhere; }
.list-row small, .data-row small, .plan-node small { display: block; margin-top: 4px; color: var(--muted); font-size: 12px; line-height: 18px; overflow-wrap: anywhere; }
.state-label { color: var(--muted); font-size: 12px; white-space: nowrap; }
.data-row, .detail { padding: 16px 0; border-bottom: 1px solid var(--color-border-subtle); }
.detail h3 { margin: 8px 0; font-size: 16px; line-height: 24px; font-weight: 500; }
.detail p, .data-row p { font-size: 13px; line-height: 20px; color: var(--color-text-secondary); }
.plan-node { padding: 12px 0; border-top: 1px solid var(--color-border-subtle); }
.notice { color: var(--muted); font-size: 12px; line-height: 18px; }
.error, .send-error { color: var(--color-status-error) !important; }
.warning { color: var(--color-status-warning) !important; }
dl { display: grid; grid-template-columns: 80px minmax(0,1fr); gap: 8px 12px; font-size: 12px; line-height: 18px; }
dt { color: var(--muted); }
dd { margin: 0; min-width: 0; color: var(--color-text-secondary); }
.mono, pre, code { font-family: var(--font-mono); }
.mono { font-size: 12px; }
.break { overflow-wrap: anywhere; }
pre { max-height: 300px; overflow: auto; padding: 12px; white-space: pre-wrap; overflow-wrap: anywhere; background: var(--app-color-background-surface-under); font-size: 12px; line-height: 18px; }
details > summary { cursor: pointer; }
.field-label { display: grid; gap: 8px; margin-bottom: 16px; color: var(--color-text-secondary); font-size: 13px; line-height: 18px; }
.field-label input, .field-label select, .field-label textarea, .search input { width: 100%; min-width: 0; border: 1px solid var(--color-border); border-radius: 8px; padding: 8px 10px; background: var(--app-color-background-control); }
.search { display: flex; gap: 8px; margin-bottom: 16px; }
.button { border: 1px solid var(--color-border); border-radius: 8px; padding: 6px 12px; background: var(--app-color-background-surface); color: var(--color-text); font-size: 13px; line-height: 18px; white-space: nowrap; }
.button:hover { background: var(--color-background-secondary-ghost-hover); }
.button.primary { border-color: var(--color-text); background: var(--color-text); color: var(--app-color-background-surface); }
.button-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.config-form, .model-form, .grant-section { margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--color-border-subtle); }
.config-form textarea { resize: vertical; }
.check-label { display: flex; align-items: center; gap: 8px; margin: 12px 0; font-size: 13px; line-height: 18px; }
.check-label input { accent-color: var(--color-accent); }
.measurement-list { margin: 12px 0; }
.measurement-list > div { display: flex; justify-content: space-between; gap: 8px; padding: 4px 0; font-size: 12px; line-height: 18px; color: var(--muted); }
.measurement-list > div span:last-child { text-align: right; }
.restore-warning { margin: 16px 0; padding: 12px; border: 1px solid var(--color-border-warning); border-radius: 12.5px; background: var(--color-background-warning); color: var(--color-status-warning); font-size: 12px; line-height: 18px; }

